// screens/HotelList/index.tsx
import React, { useCallback, useEffect, useState } from 'react';
import {
    ActivityIndicator,
    FlatList,
    Image,
    SafeAreaView,
    ScrollView,
    StatusBar,
    Text,
    TextInput,
    TouchableOpacity,
    TouchableWithoutFeedback,
    View
} from 'react-native';
import Calendar_My from '../../components/Calendar_My';
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

// 导入API
import type { IHotel } from '@hotel-booking-platform/shared-types/src/domain/hotel';
import { FeatureOption, fetchFeatureOptions } from '../../api/feature';
import { fetchHotelList, HotelListParams } from '../../api/hotel';
import { fetchLocationOptions, LocationOption } from '../../api/location';
import { fetchPriceStarOptions, PriceOption, StarOption } from '../../api/price';
import { fetchSortOptions, SortOption } from '../../api/sort';

type Props = NativeStackScreenProps<RootStackParamList, 'HotelList'>;





const HotelListScreen = ({ route, navigation }: Props) => {
    const {
        city = '',
        startDate = new Date().toISOString().split('T')[0],
        endDate = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        name = '',
        brand = ''
    } = route.params || {};

    // 选项数据状态
    const [sortOptions, setSortOptions] = useState<SortOption[]>([]);
    const [locationOptions, setLocationOptions] = useState<LocationOption[]>([]);
    const [priceOptions, setPriceOptions] = useState<PriceOption[]>([]);
    const [starOptions, setStarOptions] = useState<StarOption[]>([]);
    const [featureOptions, setFeatureOptions] = useState<FeatureOption[]>([]);

    // 日期状态
    const [calendarVisible, setCalendarVisible] = useState(false);
    const [dateInfo, setDateInfo] = useState({
        startDisplay: startDate.slice(5).replace('-', '/'),
        startStr: startDate,
        endDisplay: endDate.slice(5).replace('-', '/'),
        endStr: endDate,
        nights: calculateNights(startDate, endDate)
    });

    // 酒店列表及分页
    const [hotels, setHotels] = useState<IHotel[]>([]);
    const [loading, setLoading] = useState(false);
    const [refreshing, setRefreshing] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);
    const [total, setTotal] = useState(0);

    // 筛选核心状态
    const [activeTab, setActiveTab] = useState<number | null>(null);
    const [selectedSort, setSelectedSort] = useState(''); // 默认值需要从选项加载后设置
    const [selectedLocation, setSelectedLocation] = useState('');
    const [tempPrice, setTempPrice] = useState<string[]>([]);
    const [tempStar, setTempStar] = useState<string[]>([]);
    const [tempFeatures, setTempFeatures] = useState<string[]>([]);

    // 实际应用的筛选参数（确认后更新）
    const [appliedFilters, setAppliedFilters] = useState({
        sort: '',
        location: '',
        priceRanges: [] as string[],
        stars: [] as string[],
        features: [] as string[]
    });


    // --- 筛选逻辑处理 ---
    const toggleFilterTab = (index: number) => {
        if (activeTab === index) {
            setActiveTab(null);
        } else {
            setActiveTab(index);
        }
    };

    // 辅助函数：计算晚数
    const calculateNights = (start: string, end: string) => {
        if (!start || !end) return 1;
        const s = new Date(start);
        const e = new Date(end);
        const diff = e.getTime() - s.getTime();
        const nights = Math.ceil(diff / (1000 * 60 * 60 * 24));
        return nights > 0 ? nights : 1;
    };

    // 获取筛选选项数据
    useEffect(() => {
        const loadOptions = async () => {
            try {
                const [sortRes, locRes, priceStarRes, featureRes] = await Promise.all([
                    fetchSortOptions(),
                    fetchLocationOptions(),
                    fetchPriceStarOptions(),
                    fetchFeatureOptions()
                ]);
                setSortOptions(sortRes.data.options);
                setLocationOptions(locRes.data.options);
                setPriceOptions(priceStarRes.data.priceOptions);
                setStarOptions(priceStarRes.data.starOptions);
                setFeatureOptions(featureRes.data.options);

                // 设置默认选中值（例如第一个选项）
                if (sortRes.data.options.length > 0) {
                    setSelectedSort(sortRes.data.options[0].value);
                }
                if (locRes.data.options.length > 0) {
                    setSelectedLocation(locRes.data.options[0].value);
                }
            } catch (error) {
                console.error('加载筛选选项失败', error);
            }
        };
        loadOptions();
    }, []);

    // 加载酒店列表数据
    const loadHotels = useCallback(async (pageNum: number, isRefresh = false) => {
        if (loading || (!hasMore && !isRefresh)) return;

        setLoading(true);
        try {
            const params: HotelListParams = {
                sort: appliedFilters.sort,
                location: appliedFilters.location,
                priceRanges: appliedFilters.priceRanges,
                stars: appliedFilters.stars,
                features: appliedFilters.features,
                page: pageNum,
                pageSize: 10,
                city,
                startDate: dateInfo.startStr,
                endDate: dateInfo.endStr,
                nights: dateInfo.nights,
                keyword: name || brand
            };

            const res = await fetchHotelList(params);
            const { list, hasMore: more, total: totalCount } = res.data;

            setHotels(prev => isRefresh ? list : [...prev, ...list]);
            setHasMore(more);
            setTotal(totalCount);
            setPage(pageNum);
        } catch (error) {
            console.error('加载酒店列表失败', error);
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    }, [appliedFilters, city, dateInfo, name, brand]);

    // 初始加载或筛选条件变化时刷新
    useEffect(() => {
        // 确保选项已加载且有默认值
        if (selectedSort && selectedLocation) {
            setHotels([]);
            setPage(1);
            setHasMore(true);
            loadHotels(1, true);
        }
    }, [appliedFilters]);

    // 下拉刷新
    const onRefresh = () => {
        setRefreshing(true);
        setPage(1);
        setHasMore(true);
        loadHotels(1, true);
    };

    // 上滑加载更多
    const onEndReached = () => {
        if (hasMore && !loading) {
            loadHotels(page + 1);
        }
    };

    // 处理筛选确认
    const handleConfirm = () => {
        setAppliedFilters({
            sort: selectedSort,
            location: selectedLocation,
            priceRanges: tempPrice,
            stars: tempStar,
            features: tempFeatures
        });
        setActiveTab(null);
    };

    // 处理重置
    const handleReset = (type: 'priceStar' | 'features') => {
        if (type === 'priceStar') {
            setTempPrice([]);
            setTempStar([]);
        } else {
            setTempFeatures([]);
        }
    };

    // 渲染标签网格（与之前相同，但使用动态选项）
    const renderTagGrid = (
        options: { label: string; value: string }[],
        selectedValues: string[],
        onSelect: (val: string) => void
    ) => (
        <View style={styles.tagContainer}>
            {options.map((opt, idx) => {
                const isSelected = selectedValues.includes(opt.value);
                const isLastInRow = (idx + 1) % 3 === 0;
                return (
                    <TouchableOpacity
                        key={opt.value}
                        style={[
                            styles.tagItem,
                            isLastInRow && styles.tagItemNoMargin,
                            isSelected && styles.activeTagItem
                        ]}
                        onPress={() => onSelect(opt.value)}
                    >
                        <Text style={[styles.tagText, isSelected && styles.activeTagText]}>
                            {opt.label}
                        </Text>
                    </TouchableOpacity>
                );
            })}
        </View>
    );

    // 渲染下拉内容（使用动态选项）
    const renderDropdownContent = () => {
        if (activeTab === null) return null;

        let content = null;

        // Tab 0: 排序
        if (activeTab === 0) {
            content = (
                <View style={styles.dropdownList}>
                    {sortOptions.map((option) => (
                        <TouchableOpacity
                            key={option.value}
                            style={styles.dropdownItem}
                            onPress={() => {
                                setSelectedSort(option.value);
                                setActiveTab(null);
                                // 立即应用排序（也可以等待确认，这里按原逻辑立即应用）
                                setAppliedFilters(prev => ({ ...prev, sort: option.value }));
                            }}
                        >
                            <Text style={[styles.dropdownItemText, selectedSort === option.value && styles.activeDropdownItemText]}>
                                {option.label}
                            </Text>
                            {selectedSort === option.value && <Text style={styles.checkIcon}>✓</Text>}
                        </TouchableOpacity>
                    ))}
                </View>
            );
        }
        // Tab 1: 位置
        else if (activeTab === 1) {
            content = (
                <View style={styles.dropdownList}>
                    {locationOptions.map((option) => (
                        <TouchableOpacity
                            key={option.value}
                            style={styles.dropdownItem}
                            onPress={() => {
                                setSelectedLocation(option.value);
                                setActiveTab(null);
                                setAppliedFilters(prev => ({ ...prev, location: option.value }));
                            }}
                        >
                            <Text style={[styles.dropdownItemText, selectedLocation === option.value && styles.activeDropdownItemText]}>
                                {option.label}
                            </Text>
                            {selectedLocation === option.value && <Text style={styles.checkIcon}>✓</Text>}
                        </TouchableOpacity>
                    ))}
                </View>
            );
        }
        // Tab 2: 价格星级
        else if (activeTab === 2) {
            content = (
                <>
                    <ScrollView style={{ maxHeight: 300 }}>
                        <View style={styles.panelContainer}>
                            <Text style={styles.sectionTitle}>价格区间</Text>
                            {renderTagGrid(priceOptions, tempPrice, (val) =>
                                handleMultiSelect(tempPrice, val, setTempPrice)
                            )}

                            <Text style={styles.sectionTitle}>星级 (可多选)</Text>
                            {renderTagGrid(starOptions, tempStar, (val) =>
                                handleMultiSelect(tempStar, val, setTempStar)
                            )}
                        </View>
                    </ScrollView>
                    <View style={styles.buttonGroup}>
                        <TouchableOpacity style={styles.resetBtn} onPress={() => handleReset('priceStar')}>
                            <Text style={styles.resetBtnText}>重置</Text>
                        </TouchableOpacity>
                        <TouchableOpacity style={styles.confirmBtn} onPress={handleConfirm}>
                            <Text style={styles.confirmBtnText}>确认</Text>
                        </TouchableOpacity>
                    </View>
                </>
            );
        }
        // Tab 3: 设施
        else if (activeTab === 3) {
            content = (
                <>
                    <ScrollView style={{ maxHeight: 300 }}>
                        <View style={styles.panelContainer}>
                            <Text style={styles.sectionTitle}>服务设施</Text>
                            {renderTagGrid(featureOptions, tempFeatures, (val) =>
                                handleMultiSelect(tempFeatures, val, setTempFeatures)
                            )}
                        </View>
                    </ScrollView>
                    <View style={styles.buttonGroup}>
                        <TouchableOpacity style={styles.resetBtn} onPress={() => handleReset('features')}>
                            <Text style={styles.resetBtnText}>重置</Text>
                        </TouchableOpacity>
                        <TouchableOpacity style={styles.confirmBtn} onPress={handleConfirm}>
                            <Text style={styles.confirmBtnText}>确认</Text>
                        </TouchableOpacity>
                    </View>
                </>
            );
        }

        return (
            <View style={styles.dropdownContainer}>
                <TouchableWithoutFeedback onPress={() => setActiveTab(null)}>
                    <View style={styles.mask} />
                </TouchableWithoutFeedback>
                <View style={styles.dropdownContent}>
                    {content}
                </View>
            </View>
        );
    };

    // 通用多选处理函数
    const handleMultiSelect = (currentList: string[], value: string, setter: React.Dispatch<React.SetStateAction<string[]>>) => {
        if (currentList.includes(value)) {
            setter(currentList.filter(item => item !== value));
        } else {
            setter([...currentList, value]);
        }
    };

    // 渲染酒店项（保持不变）
    const renderHotelItem = ({ item }: { item: IHotel }) => (
        <TouchableOpacity
            activeOpacity={0.9}
            style={styles.hotelItem}
            onPress={() => navigation.navigate('HotelDetail', { hotelId: item.id, hotelName: item.name })}
        >
            <Image source={{ uri: item.image }} style={styles.hotelImage} />
            <View style={styles.infoArea}>
                <View>
                    <Text style={styles.hotelName} numberOfLines={1}>{item.name}</Text>
                    <View style={styles.scoreRow}>
                        <Text style={styles.scoreText}>{item.score}分</Text>
                        <Text style={styles.commentText}>{item.comments}评价</Text>
                    </View>
                    <Text style={styles.addressText} numberOfLines={1}>{item.address}</Text>
                    <View style={styles.tagRow}>
                        {item.tags.map((tag, idx) => (
                            <View key={idx} style={styles.hotelTag}>
                                <Text style={styles.hotelTagText}>{tag}</Text>
                            </View>
                        ))}
                    </View>
                </View>
                <View style={styles.priceContainer}>
                    <Text style={styles.priceSymbol}>¥</Text>
                    <Text style={styles.priceText}>{item.price}</Text>
                    <Text style={styles.priceUnit}>起</Text>
                </View>
            </View>
        </TouchableOpacity>
    );

    // 获取当前排序和位置的显示文本
    const getSortLabel = () => sortOptions.find(o => o.value === selectedSort)?.label || '排序';
    const getLocationLabel = () => locationOptions.find(o => o.value === selectedLocation)?.label || '位置距离';

    const filterTabs = [
        { label: getSortLabel(), index: 0 },
        { label: getLocationLabel(), index: 1 },
        { label: '价格', index: 2 },
        { label: '筛选', index: 3 },
    ];

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" backgroundColor="#fff" />
            <View style={[styles.headerContainer, { zIndex: 10 }]}>
                {/* 搜索框（略作调整，保持不变） */}
                <View style={styles.searchBarContainer}>
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <Text style={styles.backIcon}>{'<'}</Text>
                    </TouchableOpacity>
                    <View style={styles.searchMainContent}>
                        <Text style={styles.cityText}>{city || '上海'}</Text>
                        <TouchableOpacity
                            style={styles.dateVerticalContainer}
                            onPress={() => setCalendarVisible(true)}
                        >
                            <View style={styles.dateInfoColumn}>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>住</Text>
                                    <Text style={styles.dateValue}>{dateInfo.startDisplay}</Text>
                                </View>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>离</Text>
                                    <Text style={styles.dateValue}>{dateInfo.endDisplay}</Text>
                                </View>
                            </View>
                            <Text style={styles.nightCountText}>{dateInfo.nights}晚</Text>
                        </TouchableOpacity>
                        <View style={styles.verticalDivider} />
                        <View style={styles.keywordContainer}>
                            <Text style={styles.searchIcon}>🔍</Text>
                            <TextInput
                                style={styles.keywordPlaceholder}
                                placeholderTextColor="#ccc"
                                placeholder="位置/品牌/酒店"
                            />
                        </View>
                    </View>
                </View>

                <Calendar_My
                    visible={calendarVisible}
                    onClose={() => setCalendarVisible(false)}
                    onConfirm={(data) => {
                        setDateInfo(data);
                        setCalendarVisible(false);
                    }}
                />

                {/* 筛选Tab */}
                <View style={styles.filterRow}>
                    {filterTabs.map((item) => {
                        const isActive = activeTab === item.index;
                        const hasValue = (item.index === 0 && selectedSort !== sortOptions[0]?.value) ||
                            (item.index === 1 && selectedLocation !== locationOptions[0]?.value) ||
                            (item.index === 2 && (tempPrice.length > 0 || tempStar.length > 0)) ||
                            (item.index === 3 && tempFeatures.length > 0);

                        return (
                            <TouchableOpacity
                                key={item.index}
                                style={styles.filterItem}
                                onPress={() => toggleFilterTab(item.index)}
                            >
                                <Text style={[styles.filterText, (isActive || hasValue) && styles.activeFilterText]}>
                                    {item.label}
                                </Text>
                                <Text style={[styles.arrowIcon, isActive && styles.activeArrowIcon]}>
                                    {isActive ? '▲' : '▼'}
                                </Text>
                            </TouchableOpacity>
                        );
                    })}
                </View>

                {renderDropdownContent()}
            </View>

            <FlatList
                data={hotels}
                renderItem={renderHotelItem}
                keyExtractor={item => item.id}
                onEndReached={onEndReached}
                onEndReachedThreshold={0.2}
                onRefresh={onRefresh}
                refreshing={refreshing}
                showsVerticalScrollIndicator={false}
                ListFooterComponent={
                    loading && !refreshing ? (
                        <View style={styles.footerLoading}>
                            <ActivityIndicator color="#007AFF" />
                        </View>
                    ) : (
                        <View style={{ height: 20 }} />
                    )
                }
            />
        </SafeAreaView>
    );
};


export default HotelListScreen;
